using System.Text;
using Spyro.Editor.Core.Editing;
using static Cases;

internal static class TiledCodecCases
{
    // Independent literal v4 expectation; never generated by the codec under test.
    internal const string TileJson = "{\"id\":\"00000000000000000000000000000100\",\"x\":8448,\"y\":8448,\"z\":8704,\"width\":1024,\"depth\":1024,\"floorRgb\":[80,128,112],\"materials\":" + MaterialCodecCases.PairJson + "}";
    internal const string SurfaceJson = "{\"layout\":\"ordered-flat-tiles-v1\",\"tiles\":[" + TileJson + "]}";
    internal const string SpawnJson = "{\"x\":8960,\"y\":8960,\"z\":9216,\"heading\":64}";
    internal const string Golden = "{\"kind\":\"spyro-native-fresh-level\",\"schema\":4,\"surface\":" + SurfaceJson + ",\"spawn\":" + SpawnJson +
        ",\"skyRgb\":[128,96,64],\"musicTrackId\":19,\"placements\":[" + PlacementJson + "," + MobyCodecCases.MobyJson + "]}";
    internal static NativeFreshLevelDocumentIntent Value() => MobyIntentCases.Value(true).UpgradeToTiled(TiledIntentCases.TileId);

    internal static void Run()
    {
        Check(Serialize(Value()) == Golden && Serialize(Parse(Golden)) == Golden,
            "schema4 exact independent canonical literal, order, IDs, geometry, materials, spawn and mixed placements");
        Check(Serialize(Document(Wizard())) == Canonical && Serialize(MaterialCodecCases.Value()) == MaterialCodecCases.Golden &&
            Serialize(MobyIntentCases.Value()) == MobyCodecCases.Golden &&
            Serialize(MobyIntentCases.Value(true)) == MobyCodecCases.MaterialGolden,
            "all four independent preexisting v1/v2/v3 literals remain byte-exact after schema4 work");
        var parsed = Parse(Golden);
        Check(parsed.Content is NativeFreshTiledLevelContent && parsed.LegacyContent == null && parsed.FloorMaterials == null &&
            parsed.TiledContent!.Tiles[0].Materials.Triangle0 is NativeFreshRetailTerrainMaterialIntent { SourceWadEntry: 14, TextureId: 0 } &&
            parsed.Placements[1] is NativeFreshMobyPlacementIntent { Z: 65535 },
            "schema4 parse retains actual tagged tile materials and XY-only native placement intent");
        string reordered = " {\"placements\":[" + PlacementJson + "," + MobyCodecCases.MobyJson + "],\"musicTrackId\":19,\"skyRgb\":[128,96,64],\"spawn\":" + SpawnJson +
            ",\"surface\":" + SurfaceJson + ",\"schema\":4,\"kind\":\"spyro-native-fresh-level\"}\r\n";
        Check(Serialize(Parse(reordered)) == Golden, "schema4 property order and whitespace normalize without migration");
        Check(Serialize(Parse(Golden.Replace("\"tiles\":", "\"ti\\u006ces\":"))) == Golden,
            "valid escaped field spelling canonicalizes without accepting a duplicate");
        var twice = Value().WithTiledContent(Value().TiledContent!.WithTiles([
            Value().TiledContent!.Tiles[0], TiledIntentCases.Tile(1, 10496)]));
        var reverse = twice.WithTiledContent(twice.TiledContent!.WithTiles(twice.TiledContent.Tiles.Reverse()));
        Check(Serialize(reverse) != Serialize(twice) && Parse(Serialize(reverse)).TiledContent!.Tiles.Select(t => t.EditorId)
            .SequenceEqual(reverse.TiledContent!.Tiles.Select(t => t.EditorId)), "canonical tile order is authored, never sorted by geometry or ID");

        foreach (string owner in new[] { Golden, SurfaceJson, TileJson, SpawnJson, MaterialCodecCases.PairJson })
        {
            int comma = owner.IndexOf(','); string first = owner[1..comma]; string key = first[..first.IndexOf(':')];
            foreach (string changed in new[] { owner[..^1] + ",\"unknown\":0}", "{" + owner[(comma + 1)..],
                "{" + first + "," + owner[1..], owner.Replace(key + ":", key.ToUpperInvariant() + ":") })
                Reject(() => Parse(owner == Golden ? changed : Golden.Replace(owner, changed)),
                    "each schema4 object independently rejects unknown/missing/duplicate/case-mismatched fields");
        }
        foreach (string field in new[] { "surface", "spawn", "skyRgb", "musicTrackId", "tiles", "id", "width", "depth", "floorRgb", "materials" })
        {
            string needle = "\"" + field + "\":";
            string escaped = "\"\\u" + ((int)field[0]).ToString("x4") + field[1..] + "\":";
            Reject(() => Parse(Golden.Replace(needle, needle + "null," + escaped)), "escaped duplicate schema4 field");
        }
        foreach (string field in new[] { "base", "floorMaterials", "sourceBin", "sourceHandle", "nativeOwner", "runtimeVerified", "publicationApproved" })
            Reject(() => Parse(Golden[..^1] + ",\"" + field + "\":null}"), "schema4 has no competing legacy or native authority payload");
        foreach (string owner in new[] { TileJson, SurfaceJson })
            foreach (string field in new[] { "collisionBytes", "sourceHash", "sectorIndex", "triangleIndex", "runtimeApproved" })
                Reject(() => Parse(Golden.Replace(owner, owner[..^1] + ",\"" + field + "\":0}")), "tile geometry refuses injected native payload/authority");
        foreach (string bad in new[] { Golden.Replace("\"schema\":4", "\"schema\":3"), Golden.Replace("\"schema\":4", "\"schema\":5"),
            Golden.Replace("ordered-flat-tiles-v1", "ordered-flat-tiles-v2"), Golden.Replace(SurfaceJson, "null"),
            Golden.Replace("\"tiles\":[" + TileJson + "]", "\"tiles\":null"), Golden.Replace("\"tiles\":[" + TileJson + "]", "\"tiles\":[]"),
            Golden.Replace(TileJson, "null"), Golden.Replace(TileJson, TileJson + "," + TileJson), Golden.Replace(SpawnJson, "null"),
            Golden.Replace("\"materials\":" + MaterialCodecCases.PairJson, "\"materials\":null"),
            Golden.Replace("\"z\":9216", "\"z\":9217"), Golden.Replace("\"heading\":64", "\"heading\":256"),
            Golden.Replace("\"width\":1024", "\"width\":2064"), Golden.Replace("\"depth\":1024", "\"depth\":17"),
            Golden.Replace("\"musicTrackId\":19", "\"musicTrackId\":-1"), Golden.Replace(TiledIntentCases.TileId, new string('0', 32)),
            Golden.Replace("\"floorRgb\":[80,128,112]", "\"floorRgb\":[0,0,0,255]"),
            Golden.Replace("\"skyRgb\":[128,96,64]", "\"skyRgb\":\"#806040\"") })
            Reject(() => Parse(bad), "strict schema4 grammar and actual geometry/settings validation");
        foreach (string target in new[] { "\"x\":8448", "\"y\":8448", "\"z\":8704", "\"width\":1024", "\"depth\":1024",
            "\"x\":8960", "\"y\":8960", "\"z\":9216", "\"heading\":64", "\"musicTrackId\":19", "\"schema\":4" })
            foreach (string invalid in new[] { "null", "true", "\"1\"", "1.0", "1e0", "2147483648", "-2147483649", "[]", "{}" })
                Reject(() => Parse(Golden.Replace(target, target[..(target.IndexOf(':') + 1)] + invalid)), "strict bounded integer literal at each tiled scalar");
        foreach (string color in new[] { "[80,128,112]", "[128,96,64]" })
            foreach (string invalid in new[] { "null", "[]", "[1,2]", "[1,2,3,4]", "[-1,0,0]", "[256,0,0]", "[0,0,1.0]", "[0,0,1e0]", "[0,0,\"1\"]" })
                Reject(() => Parse(Golden.Replace(color, invalid)), "exact opaque display RGB grammar");
        foreach (string escaped in new[] { "\\ud800", "\\udc00" })
        {
            Reject(() => Parse(Golden.Replace("\"id\":", "\"" + escaped + "\":")), "malformed UTF16 field name");
            Reject(() => Parse(Golden.Replace(TiledIntentCases.TileId, escaped)), "malformed UTF16 tile ID");
        }
        try
        {
            Parse(Golden.Replace(TileJson, string.Join(',', Enumerable.Repeat("null", 256))));
            throw new InvalidOperationException("Expected tile-count refusal before element construction.");
        }
        catch (InvalidDataException error)
        { Check(error.Message.Contains("1..255", StringComparison.Ordinal), "parser bounds actual tile count before inspecting invalid elements"); Refusals++; }

        byte[] input = Encoding.UTF8.GetBytes(Golden); var retained = NativeFreshLevelDocumentCodec.Parse(input); Array.Fill(input, (byte)0);
        byte[] output = NativeFreshLevelDocumentCodec.SerializeCanonical(retained); Array.Fill(output, (byte)0);
        Check(Serialize(retained) == Golden, "schema4 parse/output buffers cannot mutate retained content");
        Check(Serialize(Parse(Golden + new string(' ', 65536 - Encoding.UTF8.GetByteCount(Golden)))) == Golden,
            "schema4 retains exact64KiB input budget");
        Reject(() => Parse(Golden + new string(' ', 65537 - Encoding.UTF8.GetByteCount(Golden))), "schema4 refuses over64KiB before parsing");
        Reject(() => NativeFreshLevelDocumentCodec.Parse(new byte[] { 0xEF, 0xBB, 0xBF }.Concat(Encoding.UTF8.GetBytes(Golden)).ToArray()), "schema4 refuses BOM");
        Reject(() => NativeFreshLevelDocumentCodec.Parse(Encoding.UTF8.GetBytes(Golden).Concat(new byte[] { 0xFF }).ToArray()), "schema4 strict UTF8");
        Reject(() => Parse("/*comment*/" + Golden), "schema4 no comments");
        Reject(() => Parse(Golden[..^1] + ",}"), "schema4 no trailing comma");
        Reject(() => Parse(Golden.Replace("\"skyRgb\":[128,96,64]", "\"skyRgb\":" + new string('[', 12) + "0" + new string(']', 12))), "schema4 bounded nesting");

        var pair = NativeFreshFloorMaterialsIntent.Create(MaterialIntentCases.Retail(14), MaterialIntentCases.Retail(70));
        var many = Enumerable.Range(0, 255).Select(i => NativeFreshFlatTileIntent.Create((i + 1).ToString("x32"),
            8448 + i * 16, 8448, 8704, 16, 16, new(80, 128, 112), pair)).ToArray();
        var large = NativeFreshLevelDocumentIntent.CreateTiled(NativeFreshTiledLevelContent.Create(many,
            8449, 8449, 9216, 64, new(128, 96, 64), 19), []);
        Reject(() => NativeFreshLevelDocumentCodec.SerializeCanonical(large), "canonical byte budget independently limits even bounded valid native tile lists");
    }
}
